  @protected
  void sse_encode_property_value(PropertyValue self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case PropertyValue_Text(text: final text, sensitivity: final sensitivity):
        sse_encode_i_32(0, serializer);
        sse_encode_String(text, serializer);
        sse_encode_sensitivity_level(sensitivity, serializer);
      case PropertyValue_Number(value: final value):
        sse_encode_i_32(1, serializer);
        sse_encode_f_64(value, serializer);
      case PropertyValue_Boolean(value: final value):
        sse_encode_i_32(2, serializer);
        sse_encode_bool(value, serializer);
      case PropertyValue_RichText(
        html: final html,
        sensitivity: final sensitivity,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_String(html, serializer);
        sse_encode_sensitivity_level(sensitivity, serializer);
    }
  }

